// ============================================================
// Generic URL scraper for n8n Code node
// Handles: redirects, slug typos on ID-based URLs, bot/CAPTCHA
// walls, thin <article>/<main> extraction, and meta fallbacks.
// ============================================================

// ---- Input ----
const url = $json.url;
if (!url || !url.startsWith('http')) {
  throw new Error('No valid URL found in message.');
}

// ---- Canonicalize known ID-based URL patterns ----
// Some sites resolve articles by a numeric ID and treat the slug as
// cosmetic. If the slug is mistyped, fetching the bare ID form still
// works. Add more patterns here as you run into other sites.
function canonicalize(u) {
  const patterns = [
    { test: /dawn\.com\/news\/(\d+)/i, build: (m) => `https://www.dawn.com/news/${m[1]}` },
    { test: /tribune\.com\.pk\/story\/(\d+)/i, build: (m) => `https://tribune.com.pk/story/${m[1]}` },
  ];
  for (const p of patterns) {
    const m = u.match(p.test);
    if (m) return p.build(m);
  }
  return u;
}

const fetchUrl = canonicalize(url);

// ---- Fetch ----
const response = await this.helpers.httpRequest({
  method: 'GET',
  url: fetchUrl,
  headers: {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
    'Accept-Language': 'en-US,en;q=0.9',
    'Accept-Encoding': 'gzip, deflate, br',
    'Cache-Control': 'no-cache',
    'Pragma': 'no-cache',
    'Sec-Fetch-Dest': 'document',
    'Sec-Fetch-Mode': 'navigate',
    'Sec-Fetch-Site': 'none',
    'Sec-Fetch-User': '?1',
    'Upgrade-Insecure-Requests': '1',
    'Referer': 'https://www.google.com/'
  },
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 30000,
  maxRedirects: 10
});

const status = response.statusCode;
const html = response.body || '';

if (status >= 400) {
  throw new Error(`Request failed with status ${status} for URL: ${fetchUrl}`);
}

// ---- Shared helpers ----
function decodeEntities(str) {
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&[a-z]+;/gi, ' ');
}

function extractMeta(html, prop) {
  const re = new RegExp(`<meta[^>]+(?:property|name)=["']${prop}["'][^>]+content=["']([^"']+)["']`, 'i');
  const m = html.match(re);
  return m ? decodeEntities(m[1]).trim() : null;
}

function stripBoilerplateTags(rawHtml) {
  return rawHtml
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<header[\s\S]*?<\/header>/gi, '')
    .replace(/<aside[\s\S]*?<\/aside>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<[^>]+>/g, ' ');
}

function cleanText(rawHtml) {
  return decodeEntities(stripBoilerplateTags(rawHtml))
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractFromTag(rawHtml, tag) {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const m = rawHtml.match(re);
  return m ? m[1] : null;
}

// ---- Title, with fallbacks ----
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
let title = titleMatch ? decodeEntities(titleMatch[1]).replace(/\s+/g, ' ').trim() : null;
if (!title) title = extractMeta(html, 'og:title');
if (!title) title = fetchUrl;

// ---- Bot-block / CAPTCHA detection (used for a clearer error message only) ----
const lowerHtml = html.toLowerCase();
const blockSignals = [
  'checking your browser before accessing',
  'attention required! | cloudflare',
  'enable javascript and cookies to continue',
  'access denied',
  'are you a robot',
  'verify you are human',
  'captcha'
];
const looksBlocked = html.length < 5000 && blockSignals.some(sig => lowerHtml.includes(sig));

// ---- Content extraction, narrowest-to-widest ----
// 1) Prefer <article>, then <main>, since they usually hold the real content
//    with the least nav/footer/sidebar noise.
let text = '';
const articleHtml = extractFromTag(html, 'article');
const mainHtml = extractFromTag(html, 'main');

if (articleHtml) text = cleanText(articleHtml);
if (text.length < 100 && mainHtml) text = cleanText(mainHtml);

// 2) Fall back to the full document if narrower extraction was too thin.
if (text.length < 100) text = cleanText(html);

// 3) Last resort: meta description, so we still return something usable.
if (text.length < 100) {
  const metaDesc = extractMeta(html, 'og:description') || extractMeta(html, 'description');
  if (metaDesc) text = metaDesc;
}

const content = text.substring(0, 12000);

if (content.length < 100) {
  const reason = looksBlocked
    ? 'page appears to be behind a bot-check/CAPTCHA wall'
    : `status ${status}, raw html length ${html.length}`;
  throw new Error(`Could not extract content from URL: ${fetchUrl} (${reason})`);
}

return {
  title,
  mainContent: content,
  url: fetchUrl,
  originalUrl: url,
  statusCode: status
};

const prompt = $json.prompt;

const requestBody = {
  model: 'openai/gpt-oss-20b',
  messages: [
    {
      role: 'system',
      content: 'MSSP CTI Analyst. Output clean Markdown only. Complete ALL 8 sections — never truncate. Short bullets, finish everything.'
    },
    {
      role: 'user',
      content: prompt
    }
  ],
  temperature: 0.2,
  max_tokens: 4000
};

return { bodyString: JSON.stringify(requestBody) };

const aiResponse = $input.first().json;
const slackData     = $node['Slack Trigger4'].json;
const extractedData = $node['Extract URL & Metadata4'].json;
const articleData   = $node['Fetch & Extract Content3'].json;
const promptData    = $node['Build AI Prompt4'].json;

const raw = aiResponse?.choices?.[0]?.message?.content || '';
const advisory_id = promptData.advisory_id || 'TADV-UNKNOWN';
const today_date  = promptData.today_date  || '';
const source_url  = extractedData.url || '#';

// ── Extract metadata from markdown ───────────────────────────────────
function extractMeta(text, key) {
  const m = text.match(new RegExp(`\\*\\*${key}[:\\*]*\\*\\*[:\\s]+([^\\n]+)`,'i'));
  return m ? m[1].trim() : 'N/A';
}

// ── Smart CVE extraction ─────────────────────────────────────────────
function extractCVEs(text) {
  for (const key of ['CVE\\(s\\)', 'CVEs', 'CVE']) {
    const val = extractMeta(text, key);
    if (val !== 'N/A' && /CVE-\d{4}-\d+/i.test(val)) return val.replace(/\[\d+\]/g,'').trim();
  }
  const found = [...text.matchAll(/CVE-\d{4}-\d{4,7}/gi)].map(m => m[0].toUpperCase());
  if (found.length === 0) return 'N/A';
  return [...new Set(found)].join(', ');
}

// ── Smart CVSS extraction ────────────────────────────────────────────
function extractCVSS(text) {
  const fromMeta = extractMeta(text, 'CVSS Score');
  if (fromMeta !== 'N/A' && /\d+\.?\d*/.test(fromMeta)) return fromMeta.replace(/\[\d+\]/g,'').trim();
  const bodyMatch = text.match(/CVSS(?:\s*v\d)?(?:\s*(?:Base\s*)?Score)?[:\s]+(\d+\.?\d*)/i);
  if (bodyMatch) return bodyMatch[1];
  const looseMatch = text.match(/(?:score|rating)\s+(?:of\s+)?(\d+\.\d)/i);
  return looseMatch ? looseMatch[1] : 'N/A';
}

// ── Smart Severity extraction ────────────────────────────────────────
function extractSeverity(text) {
  const SEV_RE = /\b(critical|high|medium|moderate|low)\b/i;
  const fromMeta = extractMeta(text, 'Severity Level');
  if (fromMeta !== 'N/A') {
    const m = fromMeta.match(SEV_RE);
    if (m) return m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
  }
  const patterns = [
    /severity[:\s]+([a-z]+)/i,
    /rated\s+(critical|high|medium|moderate|low)/i,
    /(critical|high|medium|moderate|low)\s+severity/i,
    /severity\s+(?:level\s+)?(?:is\s+)?(critical|high|medium|moderate|low)/i,
  ];
  for (const pat of patterns) {
    const m = text.match(pat);
    if (m) {
      const word = (m[1] || m[2] || '').toLowerCase();
      if (SEV_RE.test(word)) return word.charAt(0).toUpperCase() + word.slice(1);
    }
  }
  const cvss = parseFloat(extractCVSS(text));
  if (!isNaN(cvss)) {
    if (cvss >= 9.0) return 'Critical';
    if (cvss >= 7.0) return 'High';
    if (cvss >= 4.0) return 'Medium';
    if (cvss > 0)    return 'Low';
  }
  return 'N/A';
}

const severity   = extractSeverity(raw);
const cvss_score = extractCVSS(raw);
const cves       = extractCVEs(raw);
const titleMatch = raw.match(/# Threat Advisory[:\s]+([^\n]+)/i);
const title      = titleMatch ? titleMatch[1].trim() : (articleData.title || 'Threat Advisory');

// ── Convert Markdown to safe HTML ────────────────────────────────────
function mdToHtml(md) {
  if (!md) return '';
  return md
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color:#1a6bb5;">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>')
    .replace(/^## (.+)$/gm, '<h3 class="section-label">$1</h3>')
    .replace(/^### (.+)$/gm, '<div class="sub-heading">$1</div>')
    .replace(/^[-*] (.+)$/gm, '<li>$1</li>')
    .replace(/^\d+\. (.+)$/gm, '<li>$1</li>')
    .replace(/((?:<li>[^<]*<\/li>\n?)+)/g, '<ul>$1</ul>')
    .replace(/^---+$/gm, '<hr style="border:none;border-top:1.5px solid #d0d8e4;margin:16px 0;">')
    .replace(/\n\n+/g, '</p><p>')
    .replace(/\n/g, '<br>')
    .replace(/^(?!<[hup]|<div|<table|<hr)/, '<p>')
    + '</p>';
}

// ── Extract section content from markdown ────────────────────────────
function extractSection(text, sectionNum, sectionName) {
  const escapedName = sectionName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(
    `##\\s+${sectionNum}\\.\\s+${escapedName}([\\s\\S]*?)(?=\\n##\\s+\\d+\\.|$)`, 'i'
  );
  const m = text.match(regex);
  return m ? m[1].trim() : '';
}

// ── Parse Threat Overview table ──────────────────────────────────────
function parseThreatOverview(text) {
  if (!text) return '';
  const cleaned = text.replace(/\[\d+\]/g, '').trim();

  // ── Try markdown table format first ─────────────────────────────
  const tableRowRE = /^\|(.+)\|$/gm;
  const allRows = [];
  let m;
  while ((m = tableRowRE.exec(cleaned)) !== null) {
    const cells = m[1].split('|').map(c => c.trim());
    if (cells.every(c => /^[-:=\s]+$/.test(c))) continue;
    if (cells.every(c => c === '')) continue;
    if (cells[0].toLowerCase().includes('field') && cells[1].toLowerCase().includes('detail')) continue;
    allRows.push(cells);
  }

  if (allRows.length > 0) {
    const BAD_VALUE = /^(unknown|n\/a|not specified|not available|none|unspecified|\[.*?\])$/i;
    const rows = allRows
      .filter(cells => cells.length >= 2)
      .filter(cells => !BAD_VALUE.test(cells[1]))
      .map(cells => `
      <tr>
        <td><strong>${cells[0].replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</strong></td>
        <td>${cells[1].replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</td>
      </tr>`).join('');

    if (rows) {
      return `
      <table class="data-table">
        <thead><tr><th>Field</th><th>Details</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
      <p class="source-note">Source: <a href="${source_url}" style="color:#1a6bb5;">${source_url}</a></p>`;
    }
  }

  // ── Fallback: old bullet format ──────────────────────────────────
  const BAD_VALUE = /^(unknown|n\/a|not specified|not available|none|unspecified|\[.*?\])$/i;

  function extract(label) {
    const m = cleaned.match(new RegExp(`[-*]?\\s*\\*{0,2}${label}\\*{0,2}\\s*:\\s*([^\\n]+)`,'i'));
    if (!m) return 'N/A';
    const val = m[1].replace(/\*\*/g,'').replace(/\[\d+\]/g,'').trim();
    return BAD_VALUE.test(val) ? 'N/A' : val;
  }

  const rows = [
    ['Threat Name/Identifier', extract('Threat Name(?:\\/Identifier)?')],
    ['Threat Type',            extract('Threat Type')],
    ['Threat Actor(s)',        extract('Threat Actors?(?:\\(s\\))?')],
    ['Motivation',             extract('Motivation')],
    ['Initial Discovery Date', extract('Initial Discovery Date')],
    ['Exploitation Status',    extract('Exploitation Status')],
  ].filter(([, value]) => value !== 'N/A' && value.trim() !== '');

  if (rows.length === 0) return `<div class="section-content">${mdToHtml(text)}</div>`;

  return `
  <table class="data-table">
    <thead><tr><th>Field</th><th>Details</th></tr></thead>
    <tbody>
      ${rows.map(([field, value]) => `
      <tr>
        <td><strong>${field.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</strong></td>
        <td>${value.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</td>
      </tr>`).join('')}
    </tbody>
  </table>
  <p class="source-note">Source: <a href="${source_url}" style="color:#1a6bb5;">${source_url}</a></p>`;
}

// ── Parse Technical Details bullet list ─────────────────────────────
function parseTechnicalDetails(text) {
  const cleaned = text.replace(/\[\d+\]/g, '').trim();
  const bulletStart = cleaned.search(/^[-*]\s+\*\*/m);
  const bulletsOnly = bulletStart > 0 ? cleaned.slice(bulletStart) : cleaned;
  const lines = bulletsOnly.split('\n').filter(l => l.trim());
  if (lines.length === 0) return `<div class="section-content">${mdToHtml(text)}</div>`;

  function renderValue(raw) {
    const parts = [];
    let last = 0;
    const codeRE = /`([^`]+)`/g;
    let cm;
    while ((cm = codeRE.exec(raw)) !== null) {
      if (cm.index > last) parts.push(raw.slice(last, cm.index).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'));
      parts.push(`<code>${cm[1].replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</code>`);
      last = cm.index + cm[0].length;
    }
    if (last < raw.length) parts.push(raw.slice(last).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'));
    return parts.join('');
  }

  const items = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const m = line.match(/^[-*]\s+\*\*([^*]+)\*\*[:\s]*(.*)/);
    if (m) {
      const label = m[1].replace(/:$/, '').trim();
      const value = m[2].replace(/\[\d+\]/g, '').trim();
      const subSteps = [];
      while (i + 1 < lines.length && /^\s+\d+\./.test(lines[i + 1])) {
        i++;
        const step = lines[i].replace(/^\s+\d+\.\s*/, '').replace(/\[\d+\]/g, '').trim();
        subSteps.push(`<li>${renderValue(step)}</li>`);
      }
      if (subSteps.length > 0) {
        items.push(`<li><strong>${label.replace(/</g,'&lt;').replace(/>/g,'&gt;')}:</strong><ol class="chain-list">${subSteps.join('')}</ol></li>`);
      } else {
        const valueHtml = value ? ` ${renderValue(value)}` : '';
        items.push(`<li><strong>${label.replace(/</g,'&lt;').replace(/>/g,'&gt;')}:</strong>${valueHtml}</li>`);
      }
      i++;
      continue;
    }
    const plain = line.replace(/^[-*]\s+/, '').replace(/\[\d+\]/g, '').trim();
    if (plain) items.push(`<li>${renderValue(plain)}</li>`);
    i++;
  }

  return `<ul class="tech-list">${items.join('\n')}</ul>`;
}

// ── Parse Affected Systems table + Enterprise Exposure ───────────────
function parseAffectedSystems(text) {
  if (!text) return `<div class="section-content">${mdToHtml(text)}</div>`;
  const cleaned = text.replace(/\[\d+\]/g, '').trim();

  const tableRowRE = /^\|(.+)\|$/gm;
  const allRows = [];
  let m;
  while ((m = tableRowRE.exec(cleaned)) !== null) {
    const cells = m[1].split('|').map(c => c.trim());
    if (cells.every(c => /^[-:=\s]+$/.test(c))) continue;
    if (cells.every(c => c === '')) continue;
    allRows.push(cells);
  }

  let tableHtml = '';
  if (allRows.length > 0) {
    const [header, ...bodyRows] = allRows;
    const colCount = header.length;
    const thCells = header.map(h =>
      `<th>${h.replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</th>`
    ).join('');
    const tdRows = bodyRows.map(row => {
      const normalized = [...row];
      while (normalized.length < colCount) normalized.push('—');
      const cells = normalized.slice(0, colCount).map(c =>
        `<td>${c.replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</td>`
      ).join('');
      return `<tr>${cells}</tr>`;
    }).join('\n');
    tableHtml = `
<table class="data-table">
  <thead><tr>${thCells}</tr></thead>
  <tbody>${tdRows}</tbody>
</table>`;
  }

  const expMatch = cleaned.match(/\*\*Enterprise Exposure[:\*]*\*\*[:\s]*([\s\S]*?)(?=\n\n|\n##|$)/i);
  const exposureHtml = expMatch
    ? `<p><strong>Enterprise Exposure:</strong> ${expMatch[1].replace(/\[\d+\]/g,'').replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;').trim()}</p>`
    : '';

  if (!tableHtml && !exposureHtml) return `<div class="section-content">${mdToHtml(text)}</div>`;
  return tableHtml + exposureHtml;
}

// ── Parse Recommendations ────────────────────────────────────────────
function parseRecommendations(text) {
  if (!text) return `<div class="section-content">${mdToHtml(text)}</div>`;
  const cleaned = text.replace(/\[\d+\]/g, '').trim();

  const HEADING_RE = /\*\*(Immediate Actions[^*]*|Medium-Term Actions[^*]*|Long-Term Actions[^*]*)\*\*/gi;
  const parts = [];
  let match;
  while ((match = HEADING_RE.exec(cleaned)) !== null) {
    parts.push({ heading: match[1].trim(), start: match.index + match[0].length });
  }

  const sections = [];
  for (let i = 0; i < parts.length; i++) {
    const bodyStart = parts[i].start;
    const bodyEnd   = i + 1 < parts.length ? parts[i+1].start - parts[i+1].heading.length - 4 : cleaned.length;
    sections.push({ heading: parts[i].heading, body: cleaned.slice(bodyStart, bodyEnd).trim() });
  }

  if (sections.length === 0) return `<div class="section-content">${mdToHtml(text)}</div>`;

  return sections.map(({ heading, body }) => {
    const lines = body.split('\n').filter(l => l.trim());
    const items = lines.map(line => {
      const numbered = line.match(/^\d+\.\s+\*\*([^*]+)\*\*[:\s]*(.*)/);
      if (numbered) {
        const label = numbered[1].replace(/:$/, '').trim();
        const value = numbered[2].replace(/\[\d+\]/g,'').trim();
        return `<li><strong>${label.replace(/</g,'&lt;').replace(/>/g,'&gt;')}:</strong> ${value.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</li>`;
      }
      const plain = line.match(/^\d+\.\s+(.*)/);
      if (plain) return `<li>${plain[1].replace(/\[\d+\]/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;').trim()}</li>`;
      const bullet = line.match(/^[-*]\s+(.*)/);
      if (bullet) return `<li>${bullet[1].replace(/\[\d+\]/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;').trim()}</li>`;
      return '';
    }).filter(Boolean).join('\n');

    return `
<div class="sub-heading">${heading.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div>
<ol>${items}</ol>`;
  }).join('');
}

// ── Parse MSSP Detection & Response ─────────────────────────────────
function parseMSSPSection(text) {
  if (!text) return `<div class="section-content">${mdToHtml(text)}</div>`;
  const cleaned = text.replace(/\[\d+\]/g, '').trim();

  const HEADING_RE = /^(?:[-*]\s*)?\*\*(Detection Coverage|Automated Response|Manual Actions|Client-Specific Notes):?\*\*:?/gim;
  const parts = [];
  let match;
  while ((match = HEADING_RE.exec(cleaned)) !== null) {
    parts.push({ heading: match[1].trim(), index: match.index, end: match.index + match[0].length });
  }

  if (parts.length === 0) return `<div class="section-content">${mdToHtml(text)}</div>`;

  const sections = parts.map((part, i) => {
    const bodyStart = part.end;
    const bodyEnd   = i + 1 < parts.length ? parts[i+1].index : cleaned.length;
    return { heading: part.heading, body: cleaned.slice(bodyStart, bodyEnd).trim() };
  });

  function renderValue(raw) {
    const parts = [];
    let last = 0;
    const codeRE = /`([^`]+)`/g;
    let cm;
    while ((cm = codeRE.exec(raw)) !== null) {
      if (cm.index > last) {
        parts.push(raw.slice(last, cm.index).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'));
      }
      parts.push(`<code>${cm[1].replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</code>`);
      last = cm.index + cm[0].length;
    }
    if (last < raw.length) {
      parts.push(raw.slice(last).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'));
    }
    return parts.join('');
  }

  return sections.map(({ heading, body }) => {
    const lines = body.split('\n').filter(l => l.trim());
    const items = lines.map(line => {
      const toolMatch = line.match(/^[-*]\s+\*\*([^*]+)\*\*[:\s]*(.*)/);
      if (toolMatch) {
        const tool  = toolMatch[1].replace(/:$/, '').trim();
        const value = renderValue(toolMatch[2].replace(/\[\d+\]/g,'').trim());
        return `<li><strong>${tool.replace(/</g,'&lt;').replace(/>/g,'&gt;')}:</strong> ${value}</li>`;
      }
      const plain = line.match(/^[-*]\s+(.*)/);
      if (plain) {
        return `<li>${renderValue(plain[1].replace(/\[\d+\]/g,'').trim())}</li>`;
      }
      return '';
    }).filter(Boolean).join('\n');

    return `
<div class="sub-heading">${heading.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div>
${items ? `<ul>${items}</ul>` : ''}`;
