// ── Parse IOC table ──────────────────────────────────────────────────
function parseIOCSection(text) {
  if (!text) return '';
  const cleaned = text.replace(/\[\d+\]/g, '').trim();

  const tableRowRE = /^\|(.+)\|$/gm;
  const allRows = [];
  let m;
  while ((m = tableRowRE.exec(cleaned)) !== null) {
    const cells = m[1].split('|').map(c => c.trim());
    if (cells.every(c => /^[-:=\s]+$/.test(c))) continue;
    if (cells.every(c => c === '')) continue;
    allRows.push(cells);
  }

  if (allRows.length === 0) return '';

  const [header, ...bodyRows] = allRows;
  const colCount = header.length;
  const thCells = header.map(h =>
    `<th>${h.replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</th>`
  ).join('');
  const tdRows = bodyRows.map(row => {
    const normalized = [...row];
    while (normalized.length < colCount) normalized.push('—');
    const cells = normalized.slice(0, colCount).map((c, i) => {
      const val = c.replace(/\*\*/g,'').replace(/</g,'&lt;').replace(/>/g,'&gt;');
      return i > 0 && i < colCount - 1
        ? `<td style="font-family:'Courier New',monospace;font-size:9.5pt;">${val}</td>`
        : `<td>${val}</td>`;
    }).join('');
    return `<tr>${cells}</tr>`;
  }).join('\n');

  return `
<table class="ioc-table">
  <thead><tr>${thCells}</tr></thead>
  <tbody>${tdRows}</tbody>
</table>
<div class="note-box">
  <strong>Note:</strong> IP addresses and domains are intentionally defanged to prevent accidental resolution or hyperlinking. Re-fang only within controlled threat intelligence platforms such as MISP, VirusTotal, or your SIEM.
</div>`;
}

// ── Parse References ─────────────────────────────────────────────────
function parseReferences(text) {
  if (!text) return '';
  const cleaned = text.replace(/^\s*\d+\.\s+/gm,'').replace(/^\s*\[\d+\]\s*/gm,'').trim();
  const lines = cleaned.split('\n').filter(l => l.trim());
  const items = lines.map(line => {
    // markdown link format: [Name](url)
    const m = line.match(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/);
    if (m) return `<li><a href="${m[2].trim()}">${m[1].trim().replace(/</g,'&lt;').replace(/>/g,'&gt;')}</a></li>`;
    // bare URL
    const urlOnly = line.match(/(https?:\/\/\S+)/);
    if (urlOnly) {
      const url = urlOnly[1].replace(/[.,)]+$/,'');
      return `<li><a href="${url}">${url.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</a></li>`;
    }
    // plain text with no URL — skip karo, yeh AI ka incomplete output hai
    return '';
  }).filter(Boolean).join('\n');
  if (!items) return `<div class="section-content">${mdToHtml(text)}</div>`;
  return `<ul class="ref-list">${items}</ul>`;
}

